request_examples.content:
{

    "GroupIdList": [ // 群组列表，必填

        "@TGS#1NVTZEAE4",

        "@TGS#1CXTZEAET"

    ],

    "ResponseFilter": { // 返回

        "GroupBaseInfoFilter": [ // 如果基础信息字段，请在此数组中添加

            "Type",

            "Name",

            "Introduction",

            "Notification"

        ],

        "MemberInfoFilter": [ // 如果需要成员信息，请添加此数组

            "Account", // 成员ID

            "Role"

        ],

        "AppDefinedDataFilter_Group": [ // 群组维度的自定义字段过滤，该默认情况是没有的

            "GroupTestData1",

            "GroupTestData2"

        ],

        "AppDefinedDataFilter_GroupMember": [ // 群成员维度自定义字段过滤，该默认情况是没有的

            "MemberDefined2",

            "MemberDefined1"

        ]

    }

}

