{

  "ActionStatus": "OK",

  "ErrorInfo": "", // 这里的 ErrorInfo 无意义，需要判断每个群组的 ErrorInfo

  "ErrorCode": 0, // 这里的 ErrorCode 无意义，需要判断每个群组的 ErrorCode

  "GroupInfo": [ // 返回结果为群组信息数组，为简单起见这里仅列出一个群

      {

          "GroupId": "@TGS#2J4SZEAEL",

          "ErrorCode": 0, // 针对该群组的返回结果

          "ErrorInfo": "" , // 针对该群组的返回结果

